using System.Reflection;
using System.Text;
using TMPro;
using UI.Fishing;
using UnityEditor;
using UnityEngine;

public class RowDiagnose
{
    public static void Run()
    {
        GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/UI/UIResultPanel.prefab");
        GameObject instance = Object.Instantiate(prefab);
        instance.hideFlags = HideFlags.DontSave;

        Transform template = instance.transform.Find("Bg/Content_Rows/Row_Template");
        StringBuilder sb = new StringBuilder();
        sb.AppendLine("template=" + (template != null) + " activeSelf=" + (template != null && template.gameObject.activeSelf)
            + " activeInHierarchy=" + (template != null && template.gameObject.activeInHierarchy)
            + " childCount=" + (template != null ? template.childCount : -1));

        if (template != null)
            for (int i = 0; i < template.childCount; i++)
                sb.AppendLine("  child[" + i + "]=" + template.GetChild(i).name + " active=" + template.GetChild(i).gameObject.activeSelf);

        UIResultFishItem clone = Object.Instantiate(template.GetComponent<UIResultFishItem>(), template.parent);
        clone.name = "diag_row";
        sb.AppendLine("clone childCount=" + clone.transform.childCount + " activeSelf=" + clone.gameObject.activeSelf);

        FieldInfo nameField = typeof(UIResultFishItem).GetField("m_nameText", BindingFlags.NonPublic | BindingFlags.Instance);
        sb.AppendLine("before SetActive, m_nameText=" + (nameField.GetValue(clone) != null));

        clone.gameObject.SetActive(true);
        sb.AppendLine("after SetActive, m_nameText=" + (nameField.GetValue(clone) != null));
        sb.AppendLine("TMP in children=" + clone.GetComponentsInChildren<TMP_Text>(true).Length);

        Object.DestroyImmediate(instance);
        Debug.Log("[RowDiagnose] " + sb);
    }
}
